mapper.select:
SELECT
    emotion,
    COUNT(*) AS count
FROM sleep_diary
WHERE user_id = #{userId}
  AND date >= #{startTime}
  AND date <= #{endTime}
  AND emotion IS NOT NULL
GROUP BY emotion
ORDER BY count DESC

SELECT
    DATE_FORMAT(create_time, #{dateFormat}) AS period,
    COUNT(*) AS total_count
FROM chat_history
WHERE user_id = #{userId}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY period
ORDER BY period ASC
